"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[40763],{73718(e,n,t){t.r(n),t.d(n,{assets:()=>c,contentTitle:()=>i,default:()=>l,frontMatter:()=>o,metadata:()=>s,toc:()=>u});const s=JSON.parse('{"id":"general/mac-bounduser-serial-set-computername-devicename-script-364","title":"Mac Bounduser Serial Set Computername Devicename Script","description":"By Fulgubbe","source":"@site/docs/general/mac-bounduser-serial-set-computername-devicename-script-364.md","sourceDirName":"general","slug":"/general/mac-bounduser-serial-set-computername-devicename-script-364","permalink":"/jc-community-archive/general/mac-bounduser-serial-set-computername-devicename-script-364","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Mac Bounduser Serial Set Computername Devicename Script","description":"By Fulgubbe"},"sidebar":"docs","previous":{"title":"Mabl Amp Jumpcloud Sso Custom Saml App Setup Guide","permalink":"/jc-community-archive/general/mabl-amp-jumpcloud-sso-custom-saml-app-setup-guide"},"next":{"title":"Mac Bounduser Serial Set Computername Devicename Script","permalink":"/jc-community-archive/general/mac-bounduser-serial-set-computername-devicename-script"}}');var a=t(74848),r=t(28453);const o={title:"Mac Bounduser Serial Set Computername Devicename Script",description:"By Fulgubbe"},i=void 0,c={},u=[];function m(e){const n={code:"code",p:"p",pre:"pre",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.p,{children:"Hi all!"}),"\n",(0,a.jsx)(n.p,{children:"I could not find a script for renaming mac computers the way i wanted to so wrote this little script (and stole some code tnx!)."}),"\n",(0,a.jsx)(n.p,{children:"It sure can be cleaned up a bit but it works and maybe it can be useful for someone else."}),"\n",(0,a.jsx)(n.p,{children:"Script fetches JC bound user from managedUsers.json and serial on Macs and renames computer-name to bounduser-serial and host names to serial then updates device names in Jumpcloud to username-serial:"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:'#!/bin/bash\n\n#Set computer name to Bound user and serial by Jacob.Lantz 2022\n\nbounduser="$(cat /opt/jc/managedUsers.json | sed -n \'s/.*"username":"//p\' | awk -F \'\\\\",\' \'{print toupper($1)}\')" \n\nserial="$(system_profiler SPHardwareDataType | grep Serial | sed -n \'s/.*: //p\')"\n\ncurrentname="$(scutil --get ComputerName)"\n\nif [ "$bounduser-$serial" = "$currentname" ]; then\n    exit 0\n    else\n\n# set the hostname, localhostname and computer name\n\nsudo scutil --set ComputerName "$bounduser-$serial"\nsudo scutil --set LocalHostName "$serial"\nsudo scutil --set HostName "$serial"\n\necho "computername changed to $bounduser-$serial"\n\nfi\n\n##\n## This API call updates the Display Name of the system record.\n##\n\n# Parse the systemKey from the conf file.\n# The conf file is JSON and can be parsed using JSON.parse() in a supported language.\nconf="$(cat /opt/jc/jcagent.conf)"\nregex=\'\\"systemKey\\":\\"([a-zA-Z0-9_]+)\\"\'\n\nif [[ ${conf} =~ $regex ]] ; then\n  systemKey="${BASH_REMATCH[1]}"\nfi\n\n# Get the current time.\nnow=$(date -u "+%a, %d %h %Y %H:%M:%S GMT")\n\n# create the string to sign from the request-line and the date\nsignstr="PUT /api/systems/${systemKey} HTTP/1.1\\ndate: ${now}"\n\n# create the signature\nsignature=$(printf "$signstr" | openssl dgst -sha256 -sign /opt/jc/client.key | openssl enc -e -a | tr -d \'\\n\')\n\n# make the api call passing the signature in the authorization header\ncurl -iq \\\n  -d "{\\"displayName\\" : \\"$bounduser-$serial\\"}" \\\n  -X "PUT" \\\n  -H "Content-Type: application/json" \\\n  -H "Accept: application/json" \\\n  -H "Date: ${now}" \\\n  -H "Authorization: Signature keyId=\\"system/${systemKey}\\",headers=\\"request-line date\\",algorithm=\\"rsa-sha256\\",signature=\\"${signature}\\"" \\\n  --url https://console.jumpcloud.com/api/systems/${systemKey}\n\nexit 0\n'})})]})}function l(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(m,{...e})}):m(e)}},28453(e,n,t){t.d(n,{R:()=>o,x:()=>i});var s=t(96540);const a={},r=s.createContext(a);function o(e){const n=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),s.createElement(r.Provider,{value:n},e.children)}}}]);